parameters.message:
=<!DOCTYPE html>
<html>
<head>
  <style>
    body {
      font-family: Arial, sans-serif;
      background: #f5f7fb;
      padding: 20px;
      color: #333;
    }

    .container {
      max-width: 650px;
      margin: auto;
      background: #ffffff;
      border-radius: 10px;
      overflow: hidden;
      border: 1px solid #e5e7eb;
    }

    .header {
      background: #111827;
      color: white;
      padding: 25px;
      text-align: center;
    }

    .content {
      padding: 30px;
    }

    .order-box {
      background: #f9fafb;
      border: 1px solid #e5e7eb;
      border-radius: 8px;
      padding: 20px;
      margin-top: 20px;
    }

    .row {
      margin-bottom: 12px;
    }

    .label {
      font-weight: bold;
      color: #111827;
    }

    .invoice-btn {
      display: inline-block;
      margin-top: 25px;
      background: #2563eb;
      color: white !important;
      text-decoration: none;
      padding: 12px 24px;
      border-radius: 6px;
      font-weight: bold;
    }

    .footer {
      padding: 20px;
      text-align: center;
      font-size: 13px;
      color: #6b7280;
      border-top: 1px solid #e5e7eb;
    }
  </style>
</head>

<body>

<div class="container">

  <div class="header">
    <h1>Order Confirmed</h1>
  </div>

  <div class="content">

    <p>
      Hi {{ $('Calculate Invoice Totals').item.json.customer_email }},
    </p>

    <p>
      Thank you for your purchase. Your order has been successfully confirmed and your invoice is ready.
    </p>

    <div class="order-box">

      <div class="row">
        <span class="label">Order ID:</span>
        {{ $('Calculate Invoice Totals').item.json.order_id }}
      </div>

      <div class="row">
        <span class="label">Invoice Number:</span>
        {{ $('Calculate Invoice Totals').item.json.invoice_number }}
      </div>

      <div class="row">
        <span class="label">Total Amount:</span>
        ₹{{ $('Calculate Invoice Totals').item.json.total }}
      </div>

    </div>

    <a class="invoice-btn"
       href="{{ $('Fetch Document Status').item.json.document_card.download_url }}">
       Download Invoice
    </a>

    <p style="margin-top:25px;">
      We will notify you once your shipment is dispatched.
    </p>

  </div>

  <div class="footer">
    Thank you for shopping with us.
  </div>

</div>

</body>
</html>

